                ResultSet rows = select.executeQuery()) {
            while (rows.next()) {
                claims.add(new ClaimRow(rows.getLong(1), rows.getString(2), rows.getDate(3).toLocalDate(),
                        rows.getDate(4).toLocalDate()));
            }
