                update.setLong(2, claim.id());
                update.addBatch();
            }
            update.executeBatch();
        }
        try (Statement alter = db.createStatement()) {
            alter.execute("ALTER TABLE claim ALTER COLUMN terms SET NOT NULL");
        }
